const risultati = document.getElementById('risultati');

async function caricaCatalogo() {
  try {
    const risposta = await fetch('/api/libri');
    if (!risposta.ok) {
      throw new Error('Risposta HTTP ' + risposta.status);
    }
    const libri = await risposta.json();
    libri.forEach((libro) => {
      const riga = document.createElement('li');
      riga.textContent = libro.titolo + ' - ' + libro.prezzo;
      risultati.appendChild(riga);
